    jobject clazz = (*env)->NewObject(env, loader, "java/lang/ClassLoader", "(II)V");

    // Transform the class
    jvmtiClassInfo classInfo = env->GetClassInfo(clazz);
    if (classInfo == NULL) {
        return JNI_FALSE;
    }

    // Add a new method to the class
    jvmtiMethod method = env->GetMethodID(classInfo, "myNewMethod", "()V");
    if (method == NULL) {
        return JNI_FALSE;
    }

    // Set the implementation of the method
    jvmtiMethodImpl impl = env->GetMethodImpl(method, myImplementation);
    if (impl == NULL) {
        return JNI_FALSE;
    }

    return JNI_TRUE;
}

JNIEXPORT jboolean JNICALL
Java_MyClassTransformer_OnDetach(JNIEnv *env, jobject thiz, jthrowablepoon obj) {
    // Detach from the JVM
    Jvmti_DetachEnvironment();
    return JNI_FALSE;
}
