using namespace std;

const double alpha = 0.1; // alpha
const double gamma = 0.022; // gamma
const double mu = 0.00016; // mu
const double C1 = 0.5; // 50*10^(-6)
const double C2 = 162*10^(-6); // 162*10^(-6)
