// Function to compute M
double M(double z, double h, double alpha) {
    return (z*z*z*z*alpha*alpha) / (16*mu) * (3*pow(1+h/alpha, 4) - 4*pow(1+h/alpha, 2) + 1 - 4*pow(1+h/alpha, 4)*log(1+h/alpha));
}

// Function to compute p
double p(double z, double h, double dh) {
    return -gamma * ((z*z*dh/dz/dz) / pow(1+(dh/dz)*(dh/dz), 3/2) - (1-alpha*dh/dz) / ((alpha+h)*sqrt(1+(dh/dz)*(dh/dz))));
}

// Finite difference scheme
void finiteDifferenceScheme(int N, double dt, double dx, double h[N+1][N+1]) {
    for (int i=1; i<=N; i++) {
        for (int j=1; j<=N; j++) {
            double z = i*dx;
            double t = j*dt;
