Вот пример многопоточной программы на языке C++ для вычисления приближенного значения интеграла методами прямоугольников, трапеций и парабол (метод Симпсона) с использованием WinAPI:
```c
#include <iostream>
#include <Windows.h>
#include <thread>
#include <mutex>
#include <random>

// константа для интеграла
const double a = 0;
const double b = 1;
const double func(double x) { return x * x; }

// методы для вычисления интеграла
double rectangleMethod(int n) {
    double h = (b - a) / n;
    double sum = 0;
    for (int i = 0; i < n; i++) {
        sum += func(a + i * h);
    }
    return sum * h;
}

double trapezoidalMethod(int n) {
    double h = (b - a) / n;
    double sum = func(a) + func(b);
    for (int i = 1; i < n; i++) {
        sum += 2 * func(a + i * h);
    }
    return sum * h / 2;
}

double simpsonMethod(int n) {
    double h = (b - a) / n;
    double sum = func(a) + func(b);
    for (int i = 1; i < n; i++) {
        sum += 4 * func(a + i * h);
    }
    return sum * h / 3;
}

int main() {
    // создаем мьютекс для синхронизации вывода
    HANDLE mutex = CreateMutex(NULL, FALSE, NULL);

    // создаем семафор для контроля потоков
    HANDLE semaphore = CreateSemaphore(NULL, 0, n, NULL);

    // создаем потоки
    std::thread threads[n];
    for (int i = 0; i < n; i++) {
        threads[i] = std::thread([&mutex, i, n]() {
            // генерируем случайное значение для задержки
            std::random_device rd;
            std::mt19937 gen(rd());
            std::uniform_real_distribution<double> dis(0.1, 0.5);
            double delay = dis(gen);

            // производим вычисления
            int method = i % 3;
            double result = 0;
            switch (method) {
                case 0:
                    result = rectangleMethod(n);
                    break;
                case 1:
                    result = trapezoidalMethod(n);
                    break;
                case 2:
                    result = simpsonMethod(n);
                    break;
            }

            // ожидаем разрешения на доступ к мьютексу
            WaitForSingleObject(semaphore, INFINITE);

            // синхронизируем доступ к переменной
            WaitForSingleObject(mutex, INFINITE);
            double totalSum = result;
            ReleaseMutex(mutex);

            // отпускаем семафор
            ReleaseSemaphore(semaphore, 1, NULL);

            //롱-очередной вывод результатов
            SweatSleep(delay * 1000);
            printf("Thread %d: result = %f\n", i, totalSum);
        });
    }

    // ожидаем завершения потоков
    for (int i = 0; i < n; i++) {
        threads[i].join();
    }

    // уничтожаем мьютекс и семафор
    CloseHandle(mutex);
    CloseHandle(semaphore);

    return 0;
}
```
